query myQuery($id: uuid!, $activeUserLocale: String!) {
  ExpenseRule (where: {isDeleted: {_eq: false}, code: {_isNull: false}, id: {_eq: $id}}){
    id
    version
    code
    calculationTypeRef
    standard
    activeFrom
    activeTo
    name
    currency {
      code
      value
      translations(where: {localeCode: {_eq: $activeUserLocale}}) {
        localeCode
        value
      }
      catalog {
        defaultLocale
      }
    }
    currencyRef
    deductionLimit
    taxesCode
    useLastCountry
    nonpayableCode
    advancePaymentCode
    countryRef
    useSingleCurrency
  }
    ExpenseRuleFlag{
      expenseRuleId
      value
      name
  }
}

query myQuery($id: uuid!){
    ExpenseRuleFlag(where: {isDeleted: {_eq: false}, expenseRuleId: {_eq: $id}}) {
      id
      version
      expenseRuleId
      code
      value
      name
  }
}

