      value
      name
  }
}

query myQuery ($activeUserLocale: String!){
     countries: CatalogEntry(where: {catalog: {version: {_eq: "v1"}, identifier: {_eq: "Country"}}}, orderBy: {value: ASC}) {
    code
    id
    value
    translations(where: {localeCode: {_eq: $activeUserLocale}}) {
