const ruleFlag = getExpenseRuleFlagById.data.data.ExpenseRuleFlag[0];

const romanianCalculationValue = ruleFlag?.value === 'true' && ruleFlag.code ===  'romanianCalculation' ? ["true"] : [];
const austrianAbroadValue = ruleFlag?.value === 'true' && ruleFlag.code === 'austrianAbroad' ? ["true"] : [];

const condition1 = advancePaymentInput?.value === additionalData.value.nvi_navigationPayload.advancePaymentCode;
const condition2 = taxesInput?.value === additionalData.value.nvi_navigationPayload.taxesCode;
const condition3 = nonPayableInput?.value === additionalData.value.nvi_navigationPayload.nonpayableCode;
const condition4 = (Array.isArray(useLastCountry?.value) && useLastCountry?.value.length > 0) === fetchCalculationRules.data.data.ExpenseRule[0].useLastCountry
const condition5 = (Array.isArray(deductionLimit?.value) && deductionLimit?.value.length > 0) === fetchCalculationRules.data.data.ExpenseRule[0].deductionLimit
const condition6 = (Array.isArray(useSingleCurrency?.value) && useSingleCurrency?.value.length > 0) === fetchCalculationRules.data.data.ExpenseRule[0].useSingleCurrency
const condition7 = JSON.stringify(romanianCalculation?.value) === JSON.stringify(romanianCalculationValue);
const condition8 = JSON.stringify(austrianAbroad?.value) === JSON.stringify(austrianAbroadValue);
const condition9 = homeCountrySelect.value === additionalData.value.nvi_navigationPayload.countryRef;

if (
    condition1 &&
    condition2 &&
    condition3 &&
    condition4 &&
    condition5 &&
    condition6 &&
    condition7 &&
    condition8 &&
    condition9
) {
  fieldValidity.setValue(false)

} else {
  fieldValidity.setValue(true)
}

transformers.script:
function transformString(input) {
  const parts = input.split(':');
  const transformed = parts[2]
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');

  return transformed;
}

return transformString

const isAustrianAbroad = austrianAbroad.value.length > 0 ? true : false;
const isRomanianCalculation = romanianCalculation.value.length > 0 ? true : false;
const flagCode = isRomanianCalculation ? "romanianCalculation" : "austrianAbroad";
const flagName = isRomanianCalculation ? "Romanian Calculation" : "Austrian Abroad"
const flagValue = (isAustrianAbroad && austrianAbroad.value.length > 0) || (isRomanianCalculation && romanianCalculation.value.length > 0) ? "true" : "false";

return getExpenseRuleFlagById?.data?.data?.ExpenseRuleFlag[0]?.expenseRuleId ?
{
    "expenseRuleFlag": {
        "id": getExpenseRuleFlagById.data.data.ExpenseRuleFlag[0].id,
        "version": getExpenseRuleFlagById.data.data.ExpenseRuleFlag[0].version,
        "expenseRule": queryParams.data.id,
        "code": flagCode,
        "name": flagName,
        "value": flagValue,
    },
    "changeMode": "UPDATE"
} : {
    "expenseRuleFlag": {
        "expenseRule": queryParams.data.id || fetchLastCalculationRule.data.data.ExpenseRule[0].id,
        "code": flagCode,
        "name": flagName,
        "value": flagValue,
    },
    "changeMode": "INSERT"
};

try{
    return queryParams.data && changeCondition.value ? window.lowcoder.formatDate(queryParams.data.activeFrom,'date.long')
 : window.lowcoder.formatDate(fetchLastCalculationRule.data.data.ExpenseRule[0].activeFrom,'date.long')
}
catch(error){
return queryParams.data && changeCondition.value ? localSplitDateFunction.value(queryParams.data.activeFrom)
 : localSplitDateFunction.value(fetchLastCalculationRule.data.data.ExpenseRule[0].activeFrom)
}

return function localFunction(date){
  if(!date)
    return ""
  return date.split('T')[0]
  .split('-')
  .reverse()
  .join('.')
}

try{
   return queryParams.data && changeCondition.value ? window.lowcoder.formatDate(queryParams.data.activeTo,'date.long')
 : window.lowcoder.formatDate(fetchLastCalculationRule.data.data.ExpenseRule[0].activeTo,'date.long')
}
catch(error){
 return queryParams.data && changeCondition.value ? localSplitDateFunction.value(queryParams.data.activeTo)
 : localSplitDateFunction.value(fetchLastCalculationRule.data.data.ExpenseRule[0].activeTo)
}

